import priceBook from '@/data/prices.pt.json';
import { SUPERMARKET_BY_ID, SUPERMARKETS } from '@/data/supermarkets';
import { RECIPE_BY_ID } from '@/data/recipes';
import type { MealPlan, Recipe, SupermarketId, Unit } from '@/types';

/**
 * Basket pricing for the Portuguese catalogue.
 *
 * Every supermarket price comes from `src/data/prices.pt.json`, generated by
 * `scripts/build-price-book.mjs`. The book stores €/kg per ingredient per store,
 * so a recipe line is priced as (grams used) × (€/kg). Quantities that are not
 * weights (a pinch, a clove, "2 onions") are converted with the typical weights
 * below, which is accurate enough to rank shops fairly and is stated in the UI
 * as an estimate.
 */

interface PriceItem {
  category: string;
  perKg: Record<string, number>;
}

const BOOK = priceBook as unknown as {
  version: string;
  currency: string;
  note: string;
  stores: SupermarketId[];
  items: Record<string, PriceItem>;
};

export const PRICES_META = {
  version: BOOK.version,
  currency: BOOK.currency,
  note: BOOK.note,
} as const;

/** Grams per unit of the recipe's own measurement. */
const UNIT_GRAMS: Record<Unit, number> = {
  g: 1,
  kg: 1000,
  ml: 1,
  l: 1000,
  tsp: 5,
  tbsp: 15,
  cup: 240,
  pinch: 0.5,
  unit: 0,
  piece: 0,
  clove: 4,
  slice: 0,
  head: 0,
  bunch: 0,
  sprig: 2,
  handful: 30,
  can: 400,
};

/** Typical weight of one countable item, by department. */
const COUNT_GRAMS: Record<string, number> = {
  'fruit-veg': 120,
  'meat-fish': 150,
  'dairy-eggs': 60,
  'bread-bakery': 40,
  baking: 15,
  'spices-herbs': 2,
  'sauces-condiments': 15,
  storecupboard: 100,
  'world-foods': 100,
  frozen: 100,
  other: 100,
};

function gramsFor(quantity: number, unit: Unit, category: string): number {
  if (!Number.isFinite(quantity) || quantity <= 0) return 0;
  const direct = UNIT_GRAMS[unit] ?? 0;
  if (direct > 0) return quantity * direct;
  if (unit === 'slice') {
    const slice = category === 'bread-bakery' ? 25 : category === 'meat-fish' ? 40 : category === 'dairy-eggs' ? 20 : 30;
    return quantity * slice;
  }
  if (unit === 'head') return quantity * (category === 'fruit-veg' ? 300 : 250);
  if (unit === 'bunch') return quantity * 30;
  return quantity * (COUNT_GRAMS[category] ?? 100);
}

export interface StoreQuote {
  store: SupermarketId;
  name: string;
  accent: string;
  /** Basket total in EUR. */
  total: number;
  /** Lines we could not price (unknown ingredient or no shelf price). */
  missing: number;
}

export interface PriceResult {
  /** One quote per selected shop, cheapest first. */
  quotes: StoreQuote[];
  best: StoreQuote | null;
  /** null when nothing could be priced. */
  perServing: number | null;
  pricedLines: number;
  missingLines: number;
}

const EMPTY_RESULT: PriceResult = {
  quotes: [],
  best: null,
  perServing: null,
  pricedLines: 0,
  missingLines: 0,
};

function roundMoney(value: number): number {
  return Math.round(value * 100) / 100;
}

/** "4,20 €" — Portuguese formatting without depending on Intl support. */
export function formatEuro(value: number): string {
  return `${value.toFixed(2).replace('.', ',')} €`;
}

interface PricedLine {
  grams: number;
  item: PriceItem | undefined;
}

function costOf(recipe: Recipe, factor: number): PricedLine[] {
  return recipe.ingredients.map((line) => {
    const item = BOOK.items[line.ingredientId];
    const category = item?.category ?? 'other';
    const grams = gramsFor(line.quantity * factor, line.unit, category);
    return { grams, item };
  });
}

function quoteFor(lines: PricedLine[], store: SupermarketId): StoreQuote {
  const market = SUPERMARKET_BY_ID[store];
  let total = 0;
  let missing = 0;
  for (const line of lines) {
    const perKg = line.item?.perKg[store];
    if (!perKg || line.grams <= 0) {
      missing += 1;
      continue;
    }
    total += (line.grams * perKg) / 1000;
  }
  return {
    store,
    name: market?.name ?? store,
    accent: market?.accent ?? '#000',
    total: roundMoney(total),
    missing,
  };
}

function compareQuotes(lines: PricedLine[], stores: SupermarketId[], servings: number): PriceResult {
  const selected = stores.length ? stores : [];
  if (!selected.length || !lines.length) return EMPTY_RESULT;

  const quotes = selected
    .map((store) => quoteFor(lines, store))
    .filter((quote) => quote.total > 0)
    .sort((a, b) => a.total - b.total);

  if (!quotes.length) return EMPTY_RESULT;

  const best = quotes[0];
  return {
    quotes,
    best,
    perServing: servings > 0 ? roundMoney(best.total / servings) : null,
    pricedLines: lines.length - best.missing,
    missingLines: best.missing,
  };
}

export interface PriceRecipeInput {
  stores: SupermarketId[];
  /** Defaults to the recipe's own serving count. */
  servings?: number;
}

/** What one dish costs for the given servings, per selected shop. */
export function priceRecipe(recipe: Recipe, { stores, servings }: PriceRecipeInput): PriceResult {
  const target = servings && servings > 0 ? servings : recipe.servings || 1;
  const base = recipe.servings && recipe.servings > 0 ? recipe.servings : target;
  return compareQuotes(costOf(recipe, target / base), stores, target);
}

export interface PricePlanInput {
  stores: SupermarketId[];
  recipesById?: Record<string, Recipe>;
}

/** The whole weekly basket, comparing the same list of shops. */
export function pricePlan(plan: MealPlan, { stores, recipesById = RECIPE_BY_ID }: PricePlanInput): PriceResult {
  const lines: PricedLine[] = [];
  let servings = 0;
  for (const item of plan.items) {
    const recipe = recipesById[item.recipeId];
    if (!recipe) continue;
    const base = recipe.servings && recipe.servings > 0 ? recipe.servings : item.servings || 1;
    lines.push(...costOf(recipe, (item.servings || base) / base));
    servings += item.servings || base;
  }
  return compareQuotes(lines, stores, servings);
}

/** Cheapest shop for this dish, for compact labels. */
export function cheapestStore(result: PriceResult): { name: string; total: number; accent: string } | null {
  if (!result.best) return null;
  return { name: result.best.name, total: result.best.total, accent: result.best.accent };
}

export const ALL_SUPERMARKETS = SUPERMARKETS;
